// Cores usadas (em ordem) nas categorias novas
const CORES_NOVAS = ["#b57bff", "#ff7bd0", "#5be0c8", "#c9c9d1", "#ff8a5b", "#7bd0ff"];

const TAMANHO_MAX_NOME = 14;
const MAX_TIERS = 12;
const CHAVE_CUSTOM = "tierlist:jogosCustom";
